function maxAgua(alturas) {
  let i = 0, j = alturas.length - 1, mejor = 0;
  while (i < j) {
    mejor = Math.max(mejor, (j - i) * Math.min(alturas[i], alturas[j]));
    if (alturas[i] < alturas[j]) i++; else j--;
  }
  return mejor;
}

solution.python:
def maxAgua(alturas):
    i, j, mejor = 0, len(alturas) - 1, 0
    while i < j:
        mejor = max(mejor, (j - i) * min(alturas[i], alturas[j]))
        if alturas[i] < alturas[j]:
            i += 1
        else:
            j -= 1
    return mejor
